class WeekScheduler:
    def __init__(self, req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str):
        self.cfg = cfg
        self.tz = cfg["tz"]
        self.step = timedelta(minutes=cfg["interval_minutes"])
        self.caps = cfg["weekly_hours"]
        self.max_run = cfg["max_consecutive_days"]
        self.min_rest = timedelta(hours=float(cfg.get("min_rest_hours") or 0))
        self.split_contracts = cfg.get("split_contracts")       # None: as greedy.py (template eligibility)
        rule = cfg["break"]
        self.brk_min_hours = float(rule["min_shift_hours"])
        self.brk_len = timedelta(minutes=rule["minutes"])
        self.brk_window = tuple(timedelta(hours=h) for h in rule["window_hours"])
        self.brk_mode = cfg.get("break_placement", "midpoint")
        self.agents = sorted(agents, key=lambda a: a.agent_id)
        self.queues = list(dict.fromkeys(req["queue"]))

        self.grid: list[datetime] = [pd.Timestamp(t).to_pydatetime() for t in sorted(set(req["interval_start_utc"]))]
        self.idx = {t: i for i, t in enumerate(self.grid)}
        n = len(self.grid)
        self.req = {q: [0] * n for q in self.queues}
        for r in req.itertuples(index=False):
            self.req[r.queue][self.idx[pd.Timestamp(r.interval_start_utc).to_pydatetime()]] = int(r.required)
        self.floor = {q: [constraints.floor(q, t, cfg) for t in self.grid] for q in self.queues}
        self.w = constraints.weight(cfg)
        # operating intervals per queue (attainment): queue_hours, else operating_hours
        self.oper = {q: [self._inside(t, queue_hours(cfg, q)) for t in self.grid] for q in self.queues}

        wanted = cfg.get("templates")
        tpls = [t for t in templates_for(cfg) if wanted is None or t.id in wanted]
        self.options: list[_Option] = []
        for day in local_days(week, self.tz):
            for tpl in tpls:
                segs = tpl.segments_utc(day, self.tz)
                ivs = [self.idx[t] for s, e in segs for t in self.grid if s <= t < e]
                hours = sum((e - s).total_seconds() for s, e in segs) / 3600.0
                if ivs:
                    self.options.append(_Option(day, tpl, segs, ivs, hours))

        self.state = {a.agent_id: _AgentState() for a in self.agents}
        self.placed: list[_Placed] = []
        self.cover = {q: [0] * n for q in self.queues}
        self.cross = {q: [0] * n for q in self.queues}

    def _inside(self, t: datetime, hours) -> bool:
        loc = t.astimezone(self._zone)
        h = loc.hour + loc.minute / 60
        return hours[0] <= h < hours[1]

    @property
    def _zone(self):
        from zoneinfo import ZoneInfo
        return ZoneInfo(self.tz)

    # ---- feasibility -------------------------------------------------------------------------------

    def _can_take(self, a: Agent, q: str, opt: _Option) -> bool:
        st = self.state[a.agent_id]
        if q not in a.skills or opt.day in st.shifts:
            return False
        if opt.tpl.is_split:
            if self.split_contracts is not None and a.contract not in self.split_contracts:
                return False
        if not eligible(opt.tpl, a.contract):
            return False
        if st.hours + opt.hours > self.caps[a.contract] + 1e-9:
            return False
        days = set(st.shifts) | {opt.day}
        run, d = 1, opt.day - timedelta(days=1)
        while d in days:
            run, d = run + 1, d - timedelta(days=1)
        d = opt.day + timedelta(days=1)
        while d in days:
            run, d = run + 1, d + timedelta(days=1)
        if run > self.max_run:
            return False
        start, end = opt.segs[0][0], opt.segs[-1][1]
        for other in st.shifts.values():
            o_start, o_end = other.opt.segs[0][0], other.opt.segs[-1][1]
            if o_start < end and start < o_end:
                return False
            if o_end <= start and start - o_end < self.min_rest:
                return False
            if end <= o_start and o_start - end < self.min_rest:
                return False
        return True

    def _pick(self, q: str, opt: _Option) -> Agent | None:
        cands = [a for a in self.agents if self._can_take(a, q, opt)]
        if not cands:
            return None
        n_q = len(self.queues)
        long_shift = opt.hours >= 8 - 1e-9
        # Keep multi-skilled agents for the queues only they can serve; full-time agents for full days.
        return min(cands, key=lambda a: (len(a.skills & set(self.queues)) if n_q > 1 else 0,
                                         (a.contract != "FT") if long_shift else (a.contract != "PT"),
                                         self.state[a.agent_id].hours / self.caps[a.contract],
                                         a.agent_id))

    # ---- placing and removing ----------------------------------------------------------------------

    def _add(self, a: Agent, q: str, opt: _Option) -> _Placed:
        p = _Placed(a, q, opt)
        st = self.state[a.agent_id]
        st.shifts[opt.day] = p
        st.hours += opt.hours
        self.placed.append(p)
        others = [o for o in self.queues if o != q and o in a.skills]
        for i in opt.ivs:
            self.cover[q][i] += 1
            for o in others:
                self.cross[o][i] += 1
        return p

    def _remove(self, p: _Placed) -> None:
        st = self.state[p.agent.agent_id]
        del st.shifts[p.opt.day]
        st.hours -= p.opt.hours
        self.placed.remove(p)
        others = [o for o in self.queues if o != p.queue and o in p.agent.skills]
        for i in p.opt.ivs:
            self.cover[p.queue][i] -= 1
            for o in others:
                self.cross[o][i] -= 1

    # ---- breaks -------------------------------------------------------------------------------------

    def _break_slots(self, p: _Placed) -> list[int]:
        start = p.opt.segs[0][0]
        lo, hi = start + self.brk_window[0], start + self.brk_window[1]
        out = []
        for i in p.opt.ivs:
            t = self.grid[i]
            if lo <= t <= hi and any(s <= t and t + self.brk_len <= e for s, e in p.opt.segs):
                out.append(i)
        return out

    def _breaks_queue(self, q: str) -> list[int]:
        """Place the breaks of the shifts on `q` (they depend only on `q`'s cover); agents on break per interval."""
        on_break = [0] * len(self.grid)
        cover, req, flo = self.cover[q], self.req[q], self.floor[q]
        for p in sorted((p for p in self.placed if p.queue == q), key=lambda p: (p.opt.segs[0][0], p.agent.agent_id)):
            p.brk = None
            if p.opt.hours < self.brk_min_hours - 1e-9:
                continue
            slots = self._break_slots(p)
            if not slots:
                continue
            if self.brk_mode == "surplus":
                start = p.opt.segs[0][0]
                ends = {start + self.brk_window[0], start + self.brk_window[1]}

                def key(i, ends=ends):
                    gross_surplus = cover[i] - req[i]
                    net_after = cover[i] - on_break[i] - 1 - max(req[i], flo[i])
                    # largest gross surplus (the rule); among ties: not on a window edge, the most cover
                    # left net of breaks, the earliest
                    return (-gross_surplus, self.grid[i] in ends, -net_after, i)
                p.brk = min(slots, key=key)
            else:
                mid = p.opt.segs[0][0] + timedelta(hours=p.opt.hours / 2)
                p.brk = min(slots, key=lambda i: (abs((self.grid[i] - mid).total_seconds()), i))
            on_break[p.brk] += 1
        return on_break

    def place_breaks(self) -> dict[str, list[int]]:
        return {q: self._breaks_queue(q) for q in self.queues}

    def _queue_badness(self, q: str) -> tuple[int, int, int]:
        """(intervals below the floor, operating intervals short net of breaks, total net shortfall) on `q`."""
        b = self._breaks_queue(q)
        c, r, f, x, op = self.cover[q], self.req[q], self.floor[q], self.cross[q], self.oper[q]
        gaps = short = depth = 0
        for i in range(len(self.grid)):
            if c[i] + self.w * x[i] < f[i]:
                gaps += 1
            if op[i] and c[i] - b[i] < r[i]:
                short += 1
                depth += r[i] - (c[i] - b[i])
        return gaps, short, depth

    # ---- shortfalls ---------------------------------------------------------------------------------

    def shortfalls(self, on_break) -> tuple[dict[str, set[int]], dict[str, set[int]]]:
        """(operating intervals short of the requirement net of breaks, intervals below a floor)."""
        short, floor_gap = {}, {}
        for q in self.queues:
            c, b, r, f, x, op = self.cover[q], on_break[q], self.req[q], self.floor[q], self.cross[q], self.oper[q]
            short[q] = {i for i in range(len(self.grid)) if op[i] and c[i] - b[i] < r[i]}
            floor_gap[q] = {i for i in range(len(self.grid)) if c[i] + self.w * x[i] < f[i]}
        return short, floor_gap

    def _badness(self, on_break, edges: bool = False) -> tuple[int, ...]:
        short, gap = self.shortfalls(on_break)
        bad = (sum(map(len, gap.values())), sum(map(len, short.values())))
        return bad + (sum(self._edge_breaks(q) for q in self.queues),) if edges else bad

    def _edge_breaks(self, q: str) -> int:
        """Shifts on `q` (breaks as last placed) whose break sits on the last start the break window
        allows because the gross surplus there is strictly the largest. Legal, but it depends on the
        window's end being inclusive; the scheduler avoids it when it costs no coverage."""
        n = 0
        cover, req = self.cover[q], self.req[q]
        for p in self.placed:
            if p.queue != q or p.brk is None or self.brk_mode != "surplus":
                continue
            if self.grid[p.brk] != p.opt.segs[0][0] + self.brk_window[1]:
                continue
            others = [cover[i] - req[i] for i in self._break_slots(p) if i != p.brk]
            if not others or cover[p.brk] - req[p.brk] > max(others):
                n += 1
        return n

    def pass_edges(self) -> None:
        """Move shifts whose break lands on the window's last start (see _edge_breaks) to another
        template, day or agent when that keeps every queue at least as covered and the hours in bound."""
        if self.brk_mode != "surplus":
            return
        hours_cap = self._hours_cap()
        on_break = self.place_breaks()
        bad = self._badness(on_break, edges=True)
        for _ in range(3):
            if bad[2] == 0:
                return
            improved = False
            for p in sorted(self.placed, key=lambda p: (p.opt.segs[0][0], p.agent.agent_id)):
                if p not in self.placed or p.brk is None:
                    continue
                q = p.queue
                self._breaks_queue(q)
                if self.grid[p.brk] != p.opt.segs[0][0] + self.brk_window[1]:
                    continue
                self._remove(p)
                total = self._hours()
                best, best_val = None, bad
                cands = [(p.agent, o) for o in self.options] + \
                        [(a, o) for a in self.agents if a is not p.agent and q in a.skills
                         for o in self.options if o.day == p.opt.day]
                for a, opt in cands:
                    if (a is p.agent and opt is p.opt) or total + opt.hours > hours_cap or not self._can_take(a, q, opt):
                        continue
                    trial = self._add(a, q, opt)
                    val = self._badness(self.place_breaks(), edges=True)
                    self._remove(trial)
                    if val < best_val:
                        best, best_val = (a, opt), val
                if best is None:
                    self._add(p.agent, q, p.opt)
                    # no relocation helps: try one more shift on the queue that day (evens out the surplus)
                    total = self._hours()
                    for a in self.agents:
                        if q not in a.skills:
                            continue
                        for opt in self.options:
                            if opt.day != p.opt.day or total + opt.hours > hours_cap or not self._can_take(a, q, opt):
                                continue
                            trial = self._add(a, q, opt)
                            val = self._badness(self.place_breaks(), edges=True)
                            self._remove(trial)
                            if val < best_val:
                                best, best_val = (a, opt), val
                if best is not None:
                    self._add(best[0], q, best[1])
                    bad, improved = best_val, True
            if not improved:
                return

    # ---- passes -------------------------------------------------------------------------------------

