        on_break = self.place_breaks()
        bad = self._badness(on_break, edges=True)
        for _ in range(3):
            if bad[2] == 0:
                return
            improved = False
            for p in sorted(self.placed, key=lambda p: (p.opt.segs[0][0], p.agent.agent_id)):
                if p not in self.placed or p.brk is None:
                    continue
                q = p.queue
                self._breaks_queue(q)
                if self.grid[p.brk] != p.opt.segs[0][0] + self.brk_window[1]:
                    continue
                self._remove(p)
                total = self._hours()
                best, best_val = None, bad
                cands = [(p.agent, o) for o in self.options] + \
                        [(a, o) for a in self.agents if a is not p.agent and q in a.skills
                         for o in self.options if o.day == p.opt.day]
                for a, opt in cands:
                    if (a is p.agent and opt is p.opt) or total + opt.hours > hours_cap or not self._can_take(a, q, opt):
                        continue
                    trial = self._add(a, q, opt)
                    val = self._badness(self.place_breaks(), edges=True)
                    self._remove(trial)
                    if val < best_val:
                        best, best_val = (a, opt), val
                if best is None:
                    self._add(p.agent, q, p.opt)
                    # no relocation helps: try one more shift on the queue that day (evens out the surplus)
                    total = self._hours()
                    for a in self.agents:
                        if q not in a.skills:
                            continue
                        for opt in self.options:
                            if opt.day != p.opt.day or total + opt.hours > hours_cap or not self._can_take(a, q, opt):
                                continue
                            trial = self._add(a, q, opt)
                            val = self._badness(self.place_breaks(), edges=True)
                            self._remove(trial)
                            if val < best_val:
                                best, best_val = (a, opt), val
                if best is not None:
                    self._add(best[0], q, best[1])
                    bad, improved = best_val, True
            if not improved:
