"""Independent SOW check: python check.py litware 2027-W11 [outdir]"""
import sys, math, json
from datetime import datetime, timedelta, timezone, date
from zoneinfo import ZoneInfo
import pandas as pd
client, week = sys.argv[1], sys.argv[2]
out = sys.argv[3] if len(sys.argv) > 3 else f"/app/out/{client}"
C = {
 "litware": dict(tz="Europe/London", g=20, op=(7,21), qh={}, sla={"priority":(0.9,30),"standard":(0.8,30),"email":(0.8,300)},
                 bound=1.45, floor=("priority",2,(7,21)), staff={"email":(9,24)}, stamp="end"),
 "northwind": dict(tz="America/Chicago", g=30, op=(6,24), qh={"vip":(8,20)}, sla={"priority":(0.9,30),"standard":(0.8,20),"vip":(0.9,20)},
                 bound=1.57, floor=("vip",1,(6,24)), staff={}, stamp="start"),
}[client]
z = ZoneInfo(C["tz"]); G = timedelta(minutes=C["g"])
def erl_req(v, aht, tgt, sec):
    if v <= 0: return 0
    a = v / (C["g"]*60) * aht
    n = max(1, math.floor(a) + 1)
    while True:
        # erlang C via recursion on Erlang B
        b = 1.0
        for k in range(1, n+1): b = a*b/(k + a*b)
        pw = n*b/(n - a*(1-b))
        sl = 1 - pw*math.exp(-(n-a)*sec/aht)
        if sl >= tgt and a/n <= 0.85: return n
        n += 1
df = pd.read_csv(f"/app/data/{client}/export_{week}.csv")
col = "interval_end_local" if C["stamp"] == "end" else "interval_start_local"
rows = {}
for r in df.itertuples(index=False):
    t = datetime.strptime(getattr(r, col) + r.utc_offset.replace(":", ""), "%Y-%m-%d %H:%M%z").astimezone(timezone.utc)
    if C["stamp"] == "end": t -= G
    t = t.replace(minute=t.minute - t.minute % C["g"])
    rows.setdefault((r.queue, t), (r.volume, r.aht_sec))
y, w = week.split("-W"); mon = date.fromisocalendar(int(y), int(w), 1)
ws = datetime(mon.year, mon.month, mon.day, tzinfo=z).astimezone(timezone.utc)
we = (datetime(mon.year, mon.month, mon.day, tzinfo=z) + timedelta(days=7)).astimezone(timezone.utc)
grid = []; t = ws
while t < we: grid.append(t); t += G
def lh(t): l = t.astimezone(z); return l.hour + l.minute/60
def opq(q, t): lo, hi = C["qh"].get(q, C["op"]); return lo <= lh(t) < hi
req = {}
for q in C["sla"]:
    for t in grid:
        v, aht = rows.get((q, t), (0, 0))
        req[q, t] = erl_req(v, aht, *C["sla"][q]) if opq(q, t) else 0
s = pd.read_csv(f"{out}/schedule.csv")
for c in ("segment_start_utc","segment_end_utc","break_start_utc"): s[c] = pd.to_datetime(s[c], utc=True)
ag = pd.read_csv(f"/app/data/agents/{client}.csv", dtype=str).set_index("agent_id")
gross = {}; brk = {}
for r in s.itertuples():
    for t in grid:
        if r.segment_start_utc <= t < r.segment_end_utc:
            gross[r.queue, t] = gross.get((r.queue, t), 0) + 1
            if r.break_minutes and r.break_start_utc < t + G and t < r.break_start_utc + timedelta(minutes=int(r.break_minutes)):
                brk[r.queue, t] = brk.get((r.queue, t), 0) + 1
V = {}
def bad(k, n=1): V[k] = V.get(k, 0) + n
exc = []
att = {}; under = 0
for q in C["sla"]:
    met = tot = 0
    for t in grid:
        net = gross.get((q,t),0) - brk.get((q,t),0)
        lo, hi = C["staff"].get(q, (0, 24))
        if req[q,t] > 0 and not (lo <= lh(t) < hi): exc.append((q, t)); continue
        under += max(0, req[q,t] - net) * C["g"]/60
        if not opq(q, t): continue
        tot += 1; met += net >= req[q,t]
    att[q] = met/tot
fq, fn, fh = C["floor"]
for t in grid:
    if fh[0] <= lh(t) < fh[1]:
        if gross.get((fq,t),0) < fn: bad("floor_gross")
        if gross.get((fq,t),0) - brk.get((fq,t),0) < fn: bad("floor_net(info)")
# per agent
for aid, g in s.groupby("agent_id"):
    a = ag.loc[aid]; g = g.sort_values("segment_start_utc")
    hrs = ((g.segment_end_utc - g.segment_start_utc).dt.total_seconds()/3600).sum()
    if hrs > {"FT":40,"PT":24}[a.contract] + 1e-9: bad("weekly_hours")
    if any(q not in a.skills.split(";") for q in g.queue): bad("skill")
    if (g.segment_start_utc.values[1:] < g.segment_end_utc.values[:-1]).any(): bad("overlap")
    g = g.assign(day=[x.astimezone(z).date() for x in g.segment_start_utc])
    days = sorted(set(g.day)); run = 1
    for d1, d2 in zip(days, days[1:]):
        run = run + 1 if (d2-d1).days == 1 else 1
        if run > 5: bad("consec"); break
    shifts = [x for _, x in g.groupby("day")]
    for x in g.itertuples():
        if x.segment_start_utc.astimezone(z).date() != (x.segment_end_utc - timedelta(seconds=1)).astimezone(z).date(): bad("crosses_midnight")
        lo, hi = C["staff"].get(x.queue, (0,24))
        if lh(x.segment_start_utc) < lo: bad("staff_hours")
        if lh(x.segment_start_utc) < C["op"][0] or (lh(x.segment_end_utc) > C["op"][1] and lh(x.segment_end_utc) != 0): bad("outside_op")
    for x1, x2 in zip(shifts, shifts[1:]):
        if x2.segment_start_utc.min() - x1.segment_end_utc.max() < timedelta(hours=11): bad("rest")
    for x in shifts:
        if len(x) > 1 and a.contract != "PT": bad("split")
        st = x.segment_start_utc.min(); L = ((x.segment_end_utc - x.segment_start_utc).dt.total_seconds()/3600).sum()
        b = x[x.break_minutes > 0]
        if L < 6:
            if len(b): bad("break_on_short")
            continue
        if len(b) != 1 or int(b.break_minutes.iloc[0]) != 20: bad("break_count"); continue
        bt = b.break_start_utc.iloc[0]; q = x.queue.iloc[0]
        if not (st + timedelta(hours=2) <= bt <= st + timedelta(hours=5)): bad("break_window"); continue
        if bt not in grid: bad("break_offgrid"); continue
        def sur(t): return gross.get((q,t),0) - req[q,t]
        cand = [t for t in grid if st + timedelta(hours=2) <= t <= st + timedelta(hours=5)
                and any(s1 <= t and t + timedelta(minutes=20) <= e1 for s1, e1 in zip(x.segment_start_utc, x.segment_end_utc))]
        cand_ex = [t for t in cand if t < st + timedelta(hours=5)]
        if sur(bt) < max(map(sur, cand)): bad("break_not_max_incl")
        if bt == st + timedelta(hours=5): bad("break_on_5h_edge(info)")
        if bt in cand_ex and sur(bt) < max(map(sur, cand_ex)): bad("break_not_max_excl")
        # 20-min break inside a 30-min interval: also check interval containing break
hours = ((s.segment_end_utc - s.segment_start_utc).dt.total_seconds()/3600).sum()
rh = sum(req.values()) * C["g"]/60
res = dict(intervals=len(grid), att={k: round(v,3) for k,v in att.items()}, sched=round(hours,1), req=round(rh,1),
           ratio=round(hours/rh,4), within=hours <= C["bound"]*rh, under=round(under,1), agents=s.agent_id.nunique(),
           exceptions=len(exc), violations=V)
print(json.dumps(res))
ev = json.load(open(f"{out}/eval.json"))
print("eval:", ev["sla"], ev.get("exception_intervals"), ev["scheduled_hours"], ev.get("required_hours"), ev["understaffed_interval_hours"])
if len(sys.argv) > 4:
    for q, t in exc: print(f"- {q} {t.strftime('%Y-%m-%dT%H:%M:%SZ')}")
EOF
